def search_algorithm(src, dsts, G, num_partitions):
    """Build a low-cost shared broadcast tree using destination and relay seeds.

    A candidate tree is grown from a source-to-seed path, then terminals are
    attached by minimum marginal-cost paths where installed links are free.
    Seeds include destinations and reachable relay clouds, allowing a common
    ingress network to be reused by several destination transfers.
    """
    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))
    bc_topology = BroadCastTopology(src, dsts, num_partitions)
    terminals = list(dict.fromkeys(dsts))

    if not terminals:
        return bc_topology

    def edge_cost(u, v, data):
        """Return a numeric link price, excluding links without a price."""
        value = data.get("cost")
        return float(value) if value is not None else float("inf")

    def tree_cost(edges):
        """Return the distinct-link cost of a candidate broadcast tree."""
        return sum(edge_cost(u, v, h[u][v]) for u, v in edges)

    def build_tree(seed_path):
        """Attach terminals by repeatedly choosing the cheapest marginal path."""
        edges = set(zip(seed_path, seed_path[1:]))
        attached = {dst for dst in terminals if dst in seed_path}

        while len(attached) < len(terminals):
            def marginal_cost(u, v, data):
                return 0.0 if (u, v) in edges else edge_cost(u, v, data)

            tree_nodes = {src}
            for u, v in edges:
                tree_nodes.add(u)
                tree_nodes.add(v)

            lengths, paths = nx.multi_source_dijkstra(
                h, list(tree_nodes), weight=marginal_cost
            )
            choices = [
                (lengths[dst], dst, paths[dst])
                for dst in terminals
                if dst not in attached and dst in paths
            ]
            if not choices:
                raise nx.NetworkXNoPath("A destination is unreachable from source")

            _, _, path = min(choices, key=lambda item: item[0])
            edges.update(zip(path, path[1:]))
            attached.update(dst for dst in terminals if dst in path)

        # The greedy attachment can create a directed cycle when a later path
        # rejoins an earlier branch.  Remove expensive redundant links before
        # scoring so candidates are compared by their actual broadcast cost.
        reduced = set(edges)
        for u, v in sorted(
            tuple(reduced),
            key=lambda edge: edge_cost(edge[0], edge[1], h[edge[0]][edge[1]]),
            reverse=True,
        ):
            reduced.remove((u, v))
            trial = nx.DiGraph()
            trial.add_nodes_from([src] + terminals)
            trial.add_edges_from(reduced)
            if not all(nx.has_path(trial, src, dst) for dst in terminals):
                reduced.add((u, v))

        return reduced

    baseline = set()
    source_lengths, source_paths = nx.single_source_dijkstra(
        h, src, weight=edge_cost
    )
    for dst in terminals:
        if dst not in source_paths:
            raise nx.NetworkXNoPath("A destination is unreachable from source")
        path = source_paths[dst]
        baseline.update(zip(path, path[1:]))

    candidates = [baseline]
    seeds = [source_paths[dst] for dst in terminals]
    seen = {tuple(path) for path in seeds}

    # A relay cloud can be a better first branch than any destination: its
    # ingress path is paid once and its outgoing links can feed many clouds.
    # Restrict to inexpensive source-reachable relays to bound repeated
    # Dijkstra work on larger provider graphs.
    relay_nodes = sorted(source_paths, key=lambda node: source_lengths[node])
    for node in relay_nodes:
        if len(seeds) >= 40:
            break
        path = source_paths[node]
        if tuple(path) in seen:
            continue
        if any(nx.has_path(h, node, dst) for dst in terminals):
            seeds.append(path)
            seen.add(tuple(path))

    # The empty source seed also evaluates the pure marginal-cost greedy tree.
    seeds.append([src])
    for path in seeds:
        candidates.append(build_tree(path))

    best_edges = min(candidates, key=tree_cost)
    tree_graph = nx.DiGraph()
    tree_graph.add_edges_from(best_edges)

    for dst in terminals:
        path = nx.dijkstra_path(tree_graph, src, dst, weight=edge_cost)
        for u, v in zip(path, path[1:]):
            for partition in range(num_partitions):
                bc_topology.append_dst_partition_path(
                    dst, partition, [u, v, G[u][v]]
                )

    return bc_topology
